// Built from core.js and public HTML. Do not edit directly; run node workers/booking-staging/build.mjs
// AURMOVA independent customer booking MVP for Cloudflare Workers + D1.
// NOTE: this is staging code. Do not deploy over aurmova-secure-api or expose internal libraries.
const SERVICES = Object.freeze(['人生蓝图解析','黄金流年蓝图解析','关系蓝图解析','亲子蓝图解析','合作蓝图解析']);
const PRICES = Object.freeze({'人生蓝图解析':168,'黄金流年蓝图解析':188,'关系蓝图解析':328,'亲子蓝图解析':328,'合作蓝图解析':388});
const DEPOSIT_PER_PROJECT = 68;
const COMBO_PRICE = 288;
const STATUSES = Object.freeze(['待订金','已联系','已付订金','已付全款','已完成','已取消','待付款','已付款']);
function calcQuote(services){
 let total=services.reduce((sum,s)=>sum+PRICES[s],0);
 const combo=services.includes('人生蓝图解析')&&services.includes('黄金流年蓝图解析');
 const discount=combo?PRICES['人生蓝图解析']+PRICES['黄金流年蓝图解析']-COMBO_PRICE:0;
 total-=discount;
 const deposit=services.length*DEPOSIT_PER_PROJECT;
 return {services,total,deposit,balance:total-deposit,discount,depositPaid:0,balancePaid:0,depositPaidAt:null,balancePaidAt:null};
}
const json = (data, status=200) => new Response(JSON.stringify(data), {status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer'}});
const page = html => new Response(html,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','X-Frame-Options':'DENY','Content-Security-Policy':"default-src 'none'; script-src 'self' 'unsafe-inline' https://challenges.cloudflare.com; style-src 'self' 'unsafe-inline'; frame-src https://challenges.cloudflare.com; connect-src 'self' https://challenges.cloudflare.com; img-src 'self' data:; base-uri 'none'; form-action 'self'; frame-ancestors 'none'"}});
const clean = (v,n=120) => typeof v==='string' ? v.trim().slice(0,n) : '';
const validGender = v => ['男','女','其他'].includes(v);
const validWhatsApp = s => /^[+\d][\d\s()-]{7,23}$/.test(s);
function validDate(value){const m=/^(\d{2})\/(\d{2})\/(\d{4})$/.exec(value);if(!m)return false;const d=Number(m[1]),mo=Number(m[2]),y=Number(m[3]),dt=new Date(y,mo-1,d),now=new Date();return y>=1900&&y<=now.getUTCFullYear()&&dt.getFullYear()===y&&dt.getMonth()===mo-1&&dt.getDate()===d&&dt.getTime()<=now.getTime()}
function reduce(n){let v=Math.abs(Number(n)||0);while(v>9)v=String(v).split('').reduce((a,b)=>a+Number(b),0);return v}
// Mirrors O position from src/engine/blueprint.js; only this final public number may be displayed.
function publicNumber(birthday){const [dd,mm,yyyy]=birthday.split('/').map(Number),d=String(dd).padStart(2,'0'),m=String(mm).padStart(2,'0'),y=String(yyyy).padStart(4,'0');const I=reduce(Number(d[0])+Number(d[1])),J=reduce(Number(m[0])+Number(m[1])),K=reduce(Number(y[0])+Number(y[1])),L=yyyy===2000?5:reduce(Number(y[2])+Number(y[3]));return reduce(reduce(I+J)+reduce(K+L))}
function validate(body){
 const name=clean(body.name,80),birthday=clean(body.birthday,10),gender=clean(body.gender,12),whatsapp=clean(body.whatsapp,25),occupation=clean(body.occupation,80),question=clean(body.question,600);
 const requested=Array.isArray(body.services)?body.services:(typeof body.service==='string'?[body.service]:[]);
 if(requested.length<1||requested.length>SERVICES.length||requested.some(s=>typeof s!=='string'||!SERVICES.includes(s))||new Set(requested).size!==requested.length)throw Error('请选择至少一项有效蓝图服务，不可重复选择。');
 const services=SERVICES.filter(s=>requested.includes(s));
 if(!name||!validGender(gender)||!validDate(birthday)||!validWhatsApp(whatsapp)||body.consent!==true||body.depositTermsAccepted!==true)throw Error('请填写有效个人资料并同意资料使用及订金规则。');
 if(!Array.isArray(body.related)||body.related.length>8)throw Error('最多可以增加8位对象。');
 const related=body.related.map(x=>({name:clean(x.name,80),gender:clean(x.gender,12),birthday:clean(x.birthday,10),service:clean(x.service,60)}));
 if(related.some(x=>!x.name||!validGender(x.gender)||!validDate(x.birthday)))throw Error('关联对象的姓名、性别或生日不正确。');
 const extra=services.filter(s=>['关系蓝图解析','亲子蓝图解析','合作蓝图解析'].includes(s));
 if(related.length&&!extra.length)throw Error('所选蓝图无需添加关联对象。');
 if(related.some(x=>x.service&&!extra.includes(x.service)))throw Error('关联对象所属蓝图没有被勾选。');
 if(extra.length>1&&related.some(x=>!x.service))throw Error('请为每位关联对象指定对应的蓝图。');
 if(extra.length===1)for(const x of related)if(!x.service)x.service=extra[0];
 if(clean(body.website,200))throw Error('提交失败，请重试。');
 return {name,birthday,gender,whatsapp,services,service:services.join('＋'),occupation,question,related,quote:calcQuote(services)};
}
async function ensureTables(db){
 await db.prepare('CREATE TABLE IF NOT EXISTS aurmova_booking_staging (id TEXT PRIMARY KEY, name TEXT NOT NULL, gender TEXT NOT NULL, birthday TEXT NOT NULL, whatsapp TEXT NOT NULL, service TEXT NOT NULL, occupation TEXT NOT NULL DEFAULT \'\', question TEXT NOT NULL DEFAULT \'\', related_json TEXT NOT NULL DEFAULT \'[]\', public_number INTEGER NOT NULL, status TEXT NOT NULL DEFAULT \'待付款\', consent_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL)').run();
 await db.prepare('CREATE TABLE IF NOT EXISTS aurmova_booking_rate_limit (key TEXT PRIMARY KEY, count INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL)').run();
 const info=await db.prepare("PRAGMA table_info('aurmova_booking_staging')").all();
 if(!(info.results||[]).some(c=>c.name==='quote_json')){
  try{await db.prepare("ALTER TABLE aurmova_booking_staging ADD COLUMN quote_json TEXT NOT NULL DEFAULT '{}'").run()}
  catch(e){if(!/duplicate column name/i.test(String(e?.message||e)))throw e}
 }
}
async function checkRate(db,request,env){
 const ip=request.headers.get('CF-Connecting-IP')||'unknown';const bucket=new Date().toISOString().slice(0,13);
 const seed=(env.RATE_LIMIT_SALT||env.OWNER_ADMIN_KEY||'')+':'+bucket+':'+ip;
 const bytes=new TextEncoder().encode(seed);const digest=await crypto.subtle.digest('SHA-256',bytes);const key=Array.from(new Uint8Array(digest)).map(x=>x.toString(16).padStart(2,'0')).join('');
 const now=new Date().toISOString();
 await db.prepare('INSERT OR IGNORE INTO aurmova_booking_rate_limit (key, count, updated_at) VALUES (?,0,?)').bind(key,now).run();
 await db.prepare('UPDATE aurmova_booking_rate_limit SET count = count + 1, updated_at = ? WHERE key = ?').bind(now,key).run();
 const row=await db.prepare('SELECT count FROM aurmova_booking_rate_limit WHERE key = ?').bind(key).first();
 return Number(row?.count||0)<=5;
}
// Staging-only safe Turnstile diagnostics: log categories, never secrets, tokens, or personal data.
async function verifyTurnstile(request,env,token){
 const diagnostic=(code,message,status=400)=>{
  console.warn('AURMOVA booking Turnstile rejection:',code);
  return {ok:false,code,message,status};
 };
 if(!env.TURNSTILE_SECRET_KEY||!env.TURNSTILE_SITE_KEY)return diagnostic('TS06','预约验证配置异常（TS06），请联系 AURMOVA。',503);
 if(!token)return diagnostic('TS03','验证码无效（TS03），请重新完成验证。');
 const ip=request.headers.get('CF-Connecting-IP')||'';
 const data=new FormData();data.append('secret',env.TURNSTILE_SECRET_KEY);data.append('response',String(token));if(ip)data.append('remoteip',ip);
 try{
  const res=await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify',{method:'POST',body:data});
  if(!res.ok)return diagnostic('TS04','验证服务暂时异常（TS04），请稍后再试。',503);
  const verification=await res.json();
  if(verification.success===true)return {ok:true};
  const codes=Array.isArray(verification['error-codes'])?verification['error-codes']:[];
  if(codes.includes('timeout-or-duplicate'))return diagnostic('TS01','验证码已过期或已使用（TS01），请重新验证后提交。');
  if(codes.includes('invalid-input-secret')||codes.includes('missing-input-secret')||codes.includes('sitekey-secret-mismatch'))return diagnostic('TS02','预约验证配置异常（TS02），请联系 AURMOVA。',503);
  if(codes.includes('invalid-input-response')||codes.includes('missing-input-response'))return diagnostic('TS03','验证码无效（TS03），请重新完成验证。');
  if(codes.includes('internal-error')||codes.includes('bad-request'))return diagnostic('TS04','验证服务暂时异常（TS04），请稍后再试。',503);
  return diagnostic('TS05','验证码未通过（TS05），请重新验证。');
 }catch(_error){
  // Avoid printing exception objects: downstream errors can contain request data.
  return diagnostic('TS04','验证服务暂时异常（TS04），请稍后再试。',503);
 }
}
function allowSameOrigin(request){const origin=request.headers.get('Origin');return !origin||origin===new URL(request.url).origin}
function authorize(request,env){const h=request.headers.get('Authorization')||'';return Boolean(env.OWNER_ADMIN_KEY&&String(env.OWNER_ADMIN_KEY).length>=24&&h==='Bearer '+env.OWNER_ADMIN_KEY)}
function phoneLink(booking){const msg='你好 AURMOVA，我已经提交预约。\n预约编号：'+booking.id+'\n项目：'+booking.service+'\n本次应付订金：RM'+booking.quote.deposit+'\n姓名：'+booking.name+'\n请协助核对 TNG 付款及预约时间。';return 'https://wa.me/60105651465?text='+encodeURIComponent(msg)}
function publicPayment(env){const value=clean(env.TNG_PAYMENT_LINK_URL,400);return /^https:\/\/[^\s/?#]+(?:[/?#][^\s]*)?$/i.test(value)?value:null}
function safePublicBooking(row){return {id:row.id,services:row.services,service:row.service,number:row.public_number,status:row.status,quote:row.quote}}
async function route(request,env,publicHtml,ownerHtml){
 const url=new URL(request.url),path=url.pathname;
 if(request.method==='GET'&&(path==='/'||path==='/booking'))return page(publicHtml.replaceAll('__TURNSTILE_SITE_KEY__',String(env.TURNSTILE_SITE_KEY||'')).replaceAll('__PRICING_DATA__',JSON.stringify({prices:PRICES,depositPerProject:DEPOSIT_PER_PROJECT,comboPrice:COMBO_PRICE})));
 if(request.method==='GET'&&path==='/owner')return page(ownerHtml);
 if(request.method==='GET'&&path==='/api/health')return json({ok:true,publicReady:Boolean(env.DB&&env.OWNER_ADMIN_KEY&&env.TURNSTILE_SECRET_KEY&&env.TURNSTILE_SITE_KEY),turnstileDiagnostics:'TS-v1',paymentLinkReady:Boolean(publicPayment(env))});
 if(!path.startsWith('/api/'))return new Response('Not found',{status:404});
 if(!env.DB)return json({error:'数据库尚未绑定，请联系管理员。'},503);
 if(path==='/api/bookings'&&request.method==='POST'){
  if(!allowSameOrigin(request))return json({error:'请求来源不正确。'},403);
  if(!env.TURNSTILE_SECRET_KEY||!env.TURNSTILE_SITE_KEY||!env.OWNER_ADMIN_KEY||String(env.OWNER_ADMIN_KEY).length<24)return json({error:'预约入口尚未完成安全设置，请联系 AURMOVA。'},503);
  const raw=await request.text();if(raw.length>10000)return json({error:'资料内容过长。'},413);
  let body;try{body=JSON.parse(raw)}catch{return json({error:'资料格式不正确。'},400)}
  let record;try{record=validate(body)}catch(ex){return json({error:ex.message},400)}
  const turnstileResult=await verifyTurnstile(request,env,body.turnstileToken);if(!turnstileResult.ok)return json({error:turnstileResult.message},turnstileResult.status);
  await ensureTables(env.DB);
  if(!await checkRate(env.DB,request,env))return json({error:'提交次数较多，请稍后再试。'},429);
  const now=new Date().toISOString();const random=Array.from(crypto.getRandomValues(new Uint8Array(6))).map(x=>x.toString(16).padStart(2,'0')).join('').toUpperCase();const id='AUR-'+now.slice(2,10).replaceAll('-','')+'-'+random;
  const number=publicNumber(record.birthday);
  const row={...record,id,public_number:number,status:'待订金'};
  await env.DB.prepare('INSERT INTO aurmova_booking_staging (id,name,gender,birthday,whatsapp,service,occupation,question,related_json,public_number,status,consent_at,created_at,updated_at,quote_json) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(id,record.name,record.gender,record.birthday,record.whatsapp,record.service,record.occupation,record.question,JSON.stringify(record.related),number,'待订金',now,now,now,JSON.stringify(record.quote)).run();
  return json({booking:safePublicBooking(row),paymentUrl:publicPayment(env),whatsappUrl:phoneLink(row)},201);
 }
 if(path.startsWith('/api/owner/')){
  if(!authorize(request,env))return json({error:'管理员验证失败。'},401);
  await ensureTables(env.DB);
  if(path==='/api/owner/bookings'&&request.method==='GET'){
   const all=await env.DB.prepare('SELECT id,name,gender,birthday,whatsapp,service,occupation,question,related_json,public_number,status,created_at,quote_json FROM aurmova_booking_staging ORDER BY created_at DESC LIMIT 100').all();
   return json({bookings:(all.results||[]).map(r=>({id:r.id,name:r.name,gender:r.gender,birthday:r.birthday,whatsapp:r.whatsapp,service:r.service,occupation:r.occupation,question:r.question,related:JSON.parse(r.related_json||'[]'),number:r.public_number,status:r.status,created_at:r.created_at,quote:JSON.parse(r.quote_json||'{}')}))});
  }
  const match=/^\/api\/owner\/bookings\/(AUR-\d{6}-[A-F0-9]{12})$/.exec(path);
  if(match&&request.method==='PATCH'){
   if(!allowSameOrigin(request))return json({error:'来源错误。'},403);
   const raw=await request.text();if(raw.length>1000)return json({error:'内容过长。'},413);
   let body;try{body=JSON.parse(raw)}catch{return json({error:'格式错误。'},400)}
   if(!STATUSES.includes(body.status))return json({error:'状态不正确。'},400);
   const old=await env.DB.prepare('SELECT id,status,quote_json FROM aurmova_booking_staging WHERE id=?').bind(match[1]).first();
   if(!old)return json({error:'找不到预约。'},404);
   const quote=JSON.parse(old.quote_json||'{}');
   const financial=body.status==='已付订金'||body.status==='已付全款';
   if(financial&&!(Number(quote.total)>0))return json({error:'旧记录无收费明细，无法直接标记订金。'},400);
   if(body.status==='已付订金'&&Number(quote.balancePaid)>0)return json({error:'该记录已确认全款，不可降级为只付订金。'},400);
   const now=new Date().toISOString();
   if(financial){quote.depositPaid=quote.deposit;quote.depositPaidAt=quote.depositPaidAt||now}
   if(body.status==='已付全款'){quote.balancePaid=quote.balance;quote.balancePaidAt=quote.balancePaidAt||now}
   await env.DB.prepare('UPDATE aurmova_booking_staging SET status=?,quote_json=?,updated_at=? WHERE id=?').bind(body.status,JSON.stringify(quote),now,match[1]).run();
   return json({success:true,status:body.status,quote});
  }
 }
 return json({error:'Not found'},404);
}


const PUBLIC_HTML="<!doctype html>\n<html lang=\"zh-Hans\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#f9f7f2\"><title>AURMOVA | 人生蓝图预约</title><style>\n:root{--ink:#322e2a;--sub:#776c5f;--gold:#a68b5d;--line:#e4d9ca;--bg:#fbfaf7}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",\"Noto Sans SC\",sans-serif;line-height:1.6}.page{max-width:680px;margin:auto;padding:28px 18px 65px}.eyebrow{font-size:11px;letter-spacing:.25em;color:var(--gold)}header{text-align:center;padding:32px 5px 22px}h1{font-family:Georgia,serif;letter-spacing:.18em;font-size:35px;margin:5px 0 8px;font-weight:500}header p{margin:0;color:var(--sub);font-size:14px}.rule{width:80px;height:1px;background:var(--gold);margin:20px auto}.panel{border:1px solid var(--line);border-radius:16px;background:#fff;padding:23px;margin:18px 0;box-shadow:0 6px 28px #a58b6510}.panel h2{font-size:18px;margin:0 0 5px;font-weight:600}.hint{font-size:13px;color:var(--sub);margin:0 0 18px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:14px}.full{grid-column:1/-1}label{display:block;font-size:13px;font-weight:550;margin-bottom:5px}input,select,textarea{width:100%;border:1px solid #dbd2c6;border-radius:9px;background:#fff;min-height:45px;padding:10px 12px;font-size:15px;color:var(--ink);font-family:inherit}textarea{min-height:92px;resize:vertical}input:focus,select:focus,textarea:focus{outline:2px solid #c9b284;outline-offset:1px}.date{display:grid;grid-template-columns:1fr 1fr 1.5fr;gap:8px}.result{border:1px solid #e9dbc0;background:#fffcf7;border-radius:12px;padding:16px;text-align:center;margin-top:16px}.number{font-family:Georgia,serif;font-size:48px;color:#917143;line-height:1.2}.result small{font-size:12px;color:var(--sub)}.quote-lines{margin:12px 0}.quote-line{display:flex;align-items:center;justify-content:space-between;gap:10px;border-bottom:1px solid #ecdfcd;padding:7px 0;font-size:13px;text-align:left}.quote-line:last-child{border-bottom:0}.em{font-size:22px;color:#8a6637}.tagprice{float:right;color:#8a6637;font-size:13px}.choice{display:block;border:1px solid var(--line);border-radius:10px;padding:12px 14px;margin:9px 0;cursor:pointer}.choice input{width:auto;min-height:auto;margin-right:10px;accent-color:#987748}.choice:has(input:checked){border-color:#af9569;background:#fdfaf5}.choice b{font-size:14px}.choice span{display:block;font-size:12px;color:var(--sub);margin-left:24px}.minor{padding:12px;border:1px dashed #d9c6aa;border-radius:9px;margin:12px 0}.minor .grid{display:grid;grid-template-columns:1.2fr .8fr 1fr;gap:8px}.minor label{font-size:11px}.inline{display:flex;align-items:flex-start;gap:10px;font-size:13px;font-weight:400}.inline input{width:18px;min-height:18px;height:18px;margin-top:3px;flex:none;accent-color:#987748}.btn{border:0;border-radius:10px;background:#8e744d;color:#fff;display:block;width:100%;padding:14px 16px;font-weight:700;font-size:15px;cursor:pointer;text-decoration:none;text-align:center}.btn:disabled{background:#b6ada0;cursor:wait}.btn.outline{background:#fff;border:1px solid #bca47a;color:#806642}.btn.slim{width:auto;padding:9px 12px;font-size:12px}.notice{font-size:13px;line-height:1.8;color:#625747;background:#f7f0e5;border-radius:9px;padding:12px}.err{color:#9f3333;font-size:14px;margin:10px 0}.done{display:none}.done h2{font-size:23px}.status{color:#8d6031;font-weight:bold}footer{text-align:center;font-size:11px;color:#8c8479;padding:18px}.hidden{display:none!important}@media(max-width:470px){.fields{grid-template-columns:1fr}.minor .grid{grid-template-columns:1fr 1fr}.minor .grid>div:first-child{grid-column:1/-1}.page{padding:16px 12px 50px}.panel{padding:18px}}\n</style><script src=\"https://challenges.cloudflare.com/turnstile/v0/api.js\" async defer></script></head>\n<body><main class=\"page\"><header><div class=\"eyebrow\">PRIVATE BY DESIGN · BOOKING</div><h1>AURMOVA</h1><p>透过数字认识自己 · 透过美学展现魅力</p><div class=\"rule\"></div><p>认识你的主性格数字，预约专属蓝图咨询</p></header>\n<form id=\"booking-form\" novalidate>\n<section class=\"panel\"><h2>01 · 认识自己</h2><p class=\"hint\">请填写真实资料。出生日期格式为日／月／年。</p><div class=\"fields\"><div class=\"full\"><label for=\"name\">姓名 *</label><input id=\"name\" name=\"name\" maxlength=\"80\" autocomplete=\"name\" required placeholder=\"中文或英文姓名\"></div><div><label for=\"gender\">性别 *</label><select id=\"gender\" name=\"gender\" required><option value=\"\">请选择</option><option>女</option><option>男</option><option>其他</option></select></div><div><label for=\"whatsapp\">WhatsApp 联系号码 *</label><input id=\"whatsapp\" name=\"whatsapp\" type=\"tel\" inputmode=\"tel\" autocomplete=\"tel\" maxlength=\"25\" required placeholder=\"例如 0123456789\"></div><div class=\"full\"><label>出生日期 *（日／月／年）</label><div class=\"date\"><input id=\"day\" name=\"day\" inputmode=\"numeric\" placeholder=\"日 DD\" maxlength=\"2\" required aria-label=\"生日日期\"><input id=\"month\" name=\"month\" inputmode=\"numeric\" placeholder=\"月 MM\" maxlength=\"2\" required aria-label=\"生日月份\"><input id=\"year\" name=\"year\" inputmode=\"numeric\" placeholder=\"年 YYYY\" maxlength=\"4\" required aria-label=\"出生年份\"></div></div></div><div id=\"number-result\" class=\"result hidden\" aria-live=\"polite\"><small>你的主性格数字</small><div id=\"number\" class=\"number\">—</div><small>仅显示基础数字；完整解读由 AURMOVA 咨询提供。此数字仅作自我探索参考。</small></div></section>\n<section class=\"panel\"><h2>02 · 选择蓝图</h2><p class=\"hint\">可同时勾选多项蓝图；每项预约订金 RM68，人生＋黄金流年享 RM288 组合价，其他项目另计。</p><label class=\"choice\"><input type=\"checkbox\" name=\"service\" value=\"人生蓝图解析\"><b>人生蓝图解析</b><span>自我认识 · 性格与成长方向</span></label><label class=\"choice\"><input type=\"checkbox\" name=\"service\" value=\"黄金流年蓝图解析\"><b>黄金流年蓝图解析</b><span>年度主题 · 计划与行动节奏</span></label><label class=\"choice\"><input type=\"checkbox\" name=\"service\" value=\"关系蓝图解析\"><b>关系蓝图解析</b><span>伴侣 / 亲密关系</span></label><label class=\"choice\"><input type=\"checkbox\" name=\"service\" value=\"亲子蓝图解析\"><b>亲子蓝图解析</b><span>儿童天赋 · 家庭沟通</span></label><label class=\"choice\"><input type=\"checkbox\" name=\"service\" value=\"合作蓝图解析\"><b>合作蓝图解析</b><span>合作伙伴 / 团队沟通</span></label><div id=\"quote-preview\" class=\"result hidden\" aria-live=\"polite\"><b>本次咨询费用</b><div id=\"quote-lines\" class=\"quote-lines\"></div><div class=\"quote-line\"><b>咨询总价</b><b id=\"quote-total\">—</b></div><div class=\"quote-line\"><b>本次应付订金</b><b id=\"quote-deposit\" class=\"em\">—</b></div><div class=\"quote-line\"><span>剩余尾款（咨询前付清）</span><b id=\"quote-balance\">—</b></div><small>每项订金 RM68，从咨询总价中扣除。人生＋流年 RM288 组合优惠自动适用。</small></div><div id=\"people-section\" class=\"hidden\"><p class=\"hint\" style=\"margin-top:17px\">需要分析其他对象？每位对象须填写姓名、性别、生日；同时选关系／亲子／合作时，请标明对象所属蓝图。</p><div id=\"people\"></div><button type=\"button\" id=\"add-person\" class=\"btn outline slim\">＋ 添加对象</button></div><div class=\"fields\" style=\"margin-top:18px\"><div class=\"full\"><label for=\"occupation\">职业或身份（选填）</label><input id=\"occupation\" maxlength=\"80\" placeholder=\"例如 上班族、创业者、家长\"></div><div class=\"full\"><label for=\"question\">你最想了解的问题（选填）</label><textarea id=\"question\" maxlength=\"600\" placeholder=\"你最希望这次咨询帮助你看懂什么？\"></textarea></div></div></section>\n<section class=\"panel\"><h2>03 · 提交预约</h2><p class=\"notice\">本页先收预约订金（每项目 RM68，计入总价），剩余尾款需在咨询前付清。提交申请不代表付款或时段已确认。TNG Business 收款商户名称：TAN JOE PIN（AURMOVA 收款账户），付款金额由顾客自行填写；到账由 AURMOVA 人工核对。</p><div style=\"margin-top:16px\"><label class=\"inline\"><input type=\"checkbox\" id=\"consent\" required><span>我同意 AURMOVA 为联系、预约与提供所选咨询服务而收集、保存和使用上述资料；如填写未成年人资料，我确认已取得监护人授权。*</span></label></div><p class=\"notice\">预约确认后订金原则上不退；至少提前24小时可申请免费改期一次。依法享有的退款权利，以及 AURMOVA 无法提供服务时应作出的退款，不受此限制。</p><div style=\"margin:14px 0\"><label class=\"inline\"><input type=\"checkbox\" id=\"deposit-consent\" required><span>我已阅读并理解上述预约订金、尾款、改期与退款说明。*</span></label></div><div id=\"captcha\" class=\"cf-turnstile\" data-sitekey=\"__TURNSTILE_SITE_KEY__\" style=\"margin-top:18px\"></div><div style=\"position:absolute;left:-10000px\" aria-hidden=\"true\"><label>Leave this empty<input name=\"website\" id=\"website\" tabindex=\"-1\" autocomplete=\"off\"></label></div><p id=\"error\" class=\"err\" aria-live=\"polite\"></p><button id=\"submit\" type=\"submit\" class=\"btn\">提交预约 · 获取编号</button></section>\n</form><section id=\"complete\" class=\"panel done\" aria-live=\"polite\"><h2>预约申请已收到</h2><p>你的申请已安全保存。请保留以下编号：</p><div id=\"booking-id\" class=\"result\" style=\"font-weight:bold;letter-spacing:.12em\"></div><p>服务：<b id=\"booking-service\"></b></p><p>目前状态：<span class=\"status\">待订金／待人工确认</span></p><div class=\"result\"><div class=\"quote-line\"><span>咨询总价</span><b id=\"confirmed-total\">—</b></div><div class=\"quote-line\"><span>本次应付订金</span><b id=\"confirmed-deposit\" class=\"em\">—</b></div><div class=\"quote-line\"><span>剩余尾款</span><b id=\"confirmed-balance\">—</b></div></div><p class=\"notice\">请在 TNG Business 付款页面向 <b>TAN JOE PIN</b> 支付订金 <b id=\"pay-amount\">—</b>，并把预约编号填入「款项详情」（限25字符）。付款后仍须由 AURMOVA 人工核对。</p><button id=\"copy-booking\" type=\"button\" class=\"btn outline\" style=\"margin-bottom:12px\">复制预约编号（用于 TNG 款项详情）</button><a id=\"pay\" class=\"btn hidden\" target=\"_blank\" rel=\"noopener noreferrer\">前往 TNG Business 支付订金</a><a id=\"whatsapp-link\" class=\"btn outline\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"margin-top:12px\">WhatsApp 联系 AURMOVA</a><p class=\"hint\" style=\"margin-top:16px\">如需核对付款，请在 WhatsApp 提供预约编号与交易金额／时间。请勿发送身份证号码、OTP 或完整银行账户资料。</p></section><footer>© AURMOVA · 顾客预约页 · 咨询前请先预约</footer></main>\n<script>\n(function(){\n'use strict';\nvar form=document.getElementById('booking-form');var people=document.getElementById('people');var add=document.getElementById('add-person');var services=Array.from(document.querySelectorAll('[name=service]'));var maxPeople=8;var catalog=__PRICING_DATA__;\nfunction selectedServices(){return services.filter(function(x){return x.checked}).map(function(x){return x.value})}\nfunction selectedQuote(){var chosen=selectedServices();var total=chosen.reduce(function(sum,s){return sum+catalog.prices[s]},0);var combo=chosen.includes('人生蓝图解析')&&chosen.includes('黄金流年蓝图解析');var discount=combo?catalog.prices['人生蓝图解析']+catalog.prices['黄金流年蓝图解析']-catalog.comboPrice:0;total-=discount;var deposit=chosen.length*catalog.depositPerProject;return {total:total,deposit:deposit,balance:total-deposit,discount:discount}}\nfunction fmtMoney(n){return 'RM'+n}\nfunction updatePrice(){var selected=selectedServices(),quote=selectedQuote(),box=document.getElementById('quote-preview');box.classList.toggle('hidden',!selected.length);var lines=document.getElementById('quote-lines');lines.replaceChildren();\nfor(var v of selected){var line=document.createElement('div');line.className='quote-line';var name=document.createElement('span');name.textContent=v;var price=document.createElement('b');price.textContent=fmtMoney(catalog.prices[v]);line.appendChild(name);line.appendChild(price);lines.appendChild(line)}\nif(quote.discount){var disc=document.createElement('div');disc.className='quote-line';var title=document.createElement('span');title.textContent='人生＋流年组合优惠';var val=document.createElement('b');val.textContent='−'+fmtMoney(quote.discount);disc.appendChild(title);disc.appendChild(val);lines.appendChild(disc)}\ndocument.getElementById('quote-total').textContent=fmtMoney(quote.total);document.getElementById('quote-deposit').textContent=fmtMoney(quote.deposit);document.getElementById('quote-balance').textContent=fmtMoney(quote.balance)}\nservices.forEach(function(s){var label=s.closest('.choice');var price=document.createElement('strong');price.className='tagprice';price.textContent=fmtMoney(catalog.prices[s.value]);label.insertBefore(price,label.querySelector('span'))});\nfunction reduce(n){n=Math.abs(Number(n)||0);while(n>9)n=String(n).split('').reduce(function(a,b){return a+Number(b)},0);return n}\nfunction birth(day,month,year){var d=Number(day),m=Number(month),y=Number(year);if(!Number.isInteger(y)||y<1900||y>new Date().getFullYear()||!Number.isInteger(d)||!Number.isInteger(m)||m<1||m>12)return null;var dt=new Date(y,m-1,d);if(dt.getFullYear()!==y||dt.getMonth()!==m-1||dt.getDate()!==d||dt>new Date())return null;return String(d).padStart(2,'0')+'/'+String(m).padStart(2,'0')+'/'+y}\n// Only the public O-position number is computed here; never load the private consulting library.\nfunction mainNumber(d,m,y){var ds=String(d).padStart(2,'0'),ms=String(m).padStart(2,'0'),ys=String(y).padStart(4,'0');var I=reduce(reduce(Number(ds[0])+Number(ds[1]))+reduce(Number(ms[0])+Number(ms[1])));var J=reduce(reduce(Number(ys[0])+Number(ys[1]))+(y===2000?5:reduce(Number(ys[2])+Number(ys[3]))));return reduce(I+J)}\nfunction numberPreview(){var d=document.getElementById('day').value,m=document.getElementById('month').value,y=document.getElementById('year').value;var ok=birth(d,m,y);document.getElementById('number-result').classList.toggle('hidden',!ok);if(ok)document.getElementById('number').textContent=mainNumber(Number(d),Number(m),Number(y))}\n['day','month','year'].forEach(function(id){document.getElementById(id).addEventListener('input',numberPreview)});\ndocument.getElementById('copy-booking').addEventListener('click',async function(){var id=document.getElementById('booking-id').textContent;try{await navigator.clipboard.writeText(id);this.textContent='预约编号已复制'}catch(e){this.textContent='请长按预约编号复制'}});\nfunction updatePeople(){var eligible=selectedServices().filter(function(x){return ['关系蓝图解析','亲子蓝图解析','合作蓝图解析'].includes(x)});document.getElementById('people-section').classList.toggle('hidden',!eligible.length);\nfor(var box of people.children){var input=box.querySelector('[data-person=service]');if(!input)continue;var old=input.value;input.replaceChildren();var initial=document.createElement('option');initial.value='';initial.textContent='选择所属蓝图';input.appendChild(initial);for(var v of eligible){var op=document.createElement('option');op.value=v;op.textContent=v;input.appendChild(op)}if(eligible.includes(old))input.value=old;else if(eligible.length===1)input.value=eligible[0]}\n}services.forEach(function(s){s.addEventListener('change',function(){updatePeople();updatePrice()})});updatePrice();\nadd.addEventListener('click',function(){if(people.children.length>=maxPeople)return;var n=people.children.length+1;var box=document.createElement('div');box.className='minor';box.innerHTML='<div style=\"display:flex;align-items:center;justify-content:space-between;gap:6px\"><b>对象 '+n+'</b><button type=\"button\" class=\"btn outline slim remove-person\" style=\"width:auto\">移除</button></div><div class=\"grid\"><div><label>姓名 *</label><input data-person=\"name\" maxlength=\"80\" required></div><div><label>性别 *</label><select data-person=\"gender\" required><option value=\"\">请选择</option><option>女</option><option>男</option><option>其他</option></select></div><div><label>生日（日／月／年）*</label><input data-person=\"birthday\" placeholder=\"DD/MM/YYYY\" maxlength=\"10\" required></div><div><label>所属蓝图 *</label><select data-person=\"service\" required></select></div></div>';box.querySelector('.remove-person').addEventListener('click',function(){box.remove()});people.appendChild(box);updatePeople()});\nform.addEventListener('submit',async function(e){e.preventDefault();var err=document.getElementById('error');err.textContent='';var button=document.getElementById('submit');var d=document.getElementById('day').value,m=document.getElementById('month').value,y=document.getElementById('year').value;var birthday=birth(d,m,y);var selected=selectedServices();var name=document.getElementById('name').value.trim();var gender=document.getElementById('gender').value;var whatsapp=document.getElementById('whatsapp').value.trim();if(!name||!gender||!birthday||!selected.length||!whatsapp){err.textContent='请完成姓名、性别、有效生日、WhatsApp 和咨询项目。';return}if(!/^[+\\d][\\d\\s()-]{7,23}$/.test(whatsapp)){err.textContent='请输入有效的 WhatsApp 电话号码。';return}if(!document.getElementById('consent').checked){err.textContent='请先阅读并勾选资料使用同意。';return}if(!document.getElementById('deposit-consent').checked){err.textContent='请先确认订金／尾款及改期规则。';return}\nvar related=[];if(!document.getElementById('people-section').classList.contains('hidden')){for(var box of people.children){var v=function(x){return box.querySelector('[data-person='+x+']').value.trim()};var raw=v('birthday');var p=raw.match(/^(\\d{1,2})\\/(\\d{1,2})\\/(\\d{4})$/);var parsed=p?birth(p[1],p[2],p[3]):null;if(!v('name')||!v('gender')||!parsed){err.textContent='请填写每位对象的姓名、性别和正确生日（DD/MM/YYYY）。';return}if(!v('service')){err.textContent='请为关联对象选择所属蓝图。';return}related.push({name:v('name'),gender:v('gender'),birthday:parsed,service:v('service')})}}\nvar token=document.querySelector('[name=\"cf-turnstile-response\"]')?.value||'';if(!token){err.textContent='请完成验证码后再提交。';return}button.disabled=true;button.textContent='安全保存中…';try{var res=await fetch('/api/bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name,gender:gender,birthday:birthday,whatsapp:whatsapp,services:selected,depositTermsAccepted:true,occupation:document.getElementById('occupation').value.trim(),question:document.getElementById('question').value.trim(),related:related,consent:true,turnstileToken:token,website:document.getElementById('website').value})});var body=await res.json();if(!res.ok)throw Error(body.error||'提交失败，请稍后重试');document.getElementById('booking-id').textContent=body.booking.id;document.getElementById('booking-service').textContent=body.booking.services.join('、');document.getElementById('whatsapp-link').href=body.whatsappUrl;\ndocument.getElementById('confirmed-total').textContent=fmtMoney(body.booking.quote.total);\ndocument.getElementById('confirmed-deposit').textContent=fmtMoney(body.booking.quote.deposit);\ndocument.getElementById('confirmed-balance').textContent=fmtMoney(body.booking.quote.balance);\ndocument.getElementById('pay-amount').textContent=fmtMoney(body.booking.quote.deposit);var pay=document.getElementById('pay');if(body.paymentUrl){pay.href=body.paymentUrl;pay.classList.remove('hidden')}form.style.display='none';document.getElementById('complete').style.display='block';window.scrollTo({top:0,behavior:'smooth'})}catch(ex){err.textContent=ex.message||'网络错误，请重新尝试';if(window.turnstile)window.turnstile.reset()}finally{button.disabled=false;button.textContent='提交预约 · 获取编号'}})\n})();\n</script></body></html>\n";
const OWNER_HTML="<!doctype html><html lang=\"zh-Hans\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>AURMOVA | 私人预约后台</title><style>body{font-family:system-ui,\"Noto Sans SC\",sans-serif;background:#fbfaf7;color:#352e26;margin:0}main{max-width:1100px;margin:auto;padding:32px 16px}h1{font-weight:500;letter-spacing:.12em}header{border-bottom:1px solid #dec9a8;padding-bottom:18px}input,select,button{font:inherit;padding:10px;border:1px solid #c7b89f;border-radius:7px}button{background:#92754c;color:white;cursor:pointer}button:disabled{opacity:.5}form{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:18px 0}input{min-width:250px;max-width:100%}.hint{color:#766b5e;font-size:13px}.error{color:#a33}section{background:white;border:1px solid #e7dac7;border-radius:12px;margin-top:20px;padding:18px;overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid #eadfce;padding:12px 9px;text-align:left;vertical-align:top}th{white-space:nowrap}td{min-width:88px}td.details{min-width:190px;max-width:270px;white-space:pre-wrap;word-break:break-word}.pill{font-weight:bold;color:#855e27}select{padding:5px;font-size:12px;max-width:160px} .skip{background:#eee;color:#444}</style></head><body><main><header><small>AURMOVA · PRIVATE</small><h1>私人预约记录</h1><p class=\"hint\">仅限后台本人使用。这里显示顾客提交的资料；付款需按实际 TNG 交易人工核对。</p></header><form id=\"access\"><input id=\"secret\" type=\"password\" minlength=\"24\" autocomplete=\"off\" placeholder=\"输入 Cloudflare OWNER_ADMIN_KEY\" required><button type=\"submit\">查看待处理预约</button><button id=\"refresh\" type=\"button\" class=\"skip\" disabled>刷新</button></form><p id=\"err\" class=\"error\" role=\"alert\"></p><section><div id=\"count\" class=\"hint\">请先使用管理员密钥验证身份。</div><div style=\"overflow-x:auto\"><table><thead><tr><th>创建日期</th><th>预约号 / 状态</th><th>顾客</th><th>生日 / 几号人</th><th>服务</th><th>其他对象</th><th>咨询问题</th><th>人工操作</th></tr></thead><tbody id=\"rows\"></tbody></table></div></section><p class=\"hint\">请勿把此页面与管理员密钥分享给顾客。没有有效密钥无法读取预约资料。</p></main><script>\n(function(){'use strict';var key='';var err=document.getElementById('err');var rows=document.getElementById('rows');function td(value){var e=document.createElement('td');e.textContent=value??'';return e}function stamp(v){try{return new Date(v).toLocaleString('zh-MY')}catch{return v||''}}\nasync function load(){err.textContent='';var r=await fetch('/api/owner/bookings',{headers:{Authorization:'Bearer '+key},cache:'no-store'});var j=await r.json();if(!r.ok)throw Error(j.error||'无法载入预约');rows.replaceChildren();document.getElementById('count').textContent='共 '+j.bookings.length+' 份记录（最近 100 笔，最新在前）。';for(var x of j.bookings){var tr=document.createElement('tr');tr.appendChild(td(stamp(x.created_at)));var ref=td(x.id+'\\n'+x.status);ref.className='pill';tr.appendChild(ref);tr.appendChild(td(x.name+'\\n'+x.gender+'\\n'+x.whatsapp));tr.appendChild(td(x.birthday+'\\n'+x.number+'号'));tr.appendChild(td(x.service));var rel=td((x.related||[]).map(function(p){return p.name+' / '+p.gender+' / '+p.birthday}).join('\\n')||'—');rel.className='details';tr.appendChild(rel);var notes=td([x.occupation,x.question].filter(Boolean).join('\\n')||'—');notes.className='details';tr.appendChild(notes);var ops=document.createElement('td');var sel=document.createElement('select');['待付款','已付款','已联系','已完成','已取消'].forEach(function(s){var opt=document.createElement('option');opt.value=s;opt.textContent=s;sel.appendChild(opt)});sel.value=x.status;sel.addEventListener('change',async function(){var v=sel.value;if(v==='已付款'&&!window.confirm('确认已在 TNG Business 中亲自核对到这笔款项？')){sel.value=x.status;return}sel.disabled=true;try{var rr=await fetch('/api/owner/bookings/'+encodeURIComponent(x.id),{method:'PATCH',headers:{Authorization:'Bearer '+key,'Content-Type':'application/json'},body:JSON.stringify({status:v})});var b=await rr.json();if(!rr.ok)throw Error(b.error||'更新失败');await load()}catch(e){err.textContent=e.message;sel.value=x.status}finally{sel.disabled=false}});ops.appendChild(sel);tr.appendChild(ops);rows.appendChild(tr)}}\ndocument.getElementById('access').addEventListener('submit',async function(e){e.preventDefault();key=document.getElementById('secret').value.trim();try{await load();document.getElementById('refresh').disabled=false;document.getElementById('secret').value=''}catch(ex){err.textContent=ex.message;key='';document.getElementById('refresh').disabled=true}});document.getElementById('refresh').addEventListener('click',function(){load().catch(function(e){err.textContent=e.message})})\n})();\n</script></body></html>\n";
export default { async fetch(request,env){try{return await route(request,env,PUBLIC_HTML,OWNER_HTML)}catch(ex){console.error("AURMOVA booking API error",ex?.message||"unknown");return json({error:"系统暂时无法处理，请稍后再试。"},500)}} };
